#include <hb.h>
#include <hb-ot.h>
#include <stdio.h>
#include <stdlib.h>
int main(int argc,char**argv){if(argc!=2)return 1;hb_blob_t*blob=hb_blob_create_from_file_or_fail(argv[1]);if(!blob)return 2;hb_face_t*face=hb_face_create(blob,0);hb_font_t*font=hb_font_create(face);hb_ot_font_set_funcs(font);hb_font_set_scale(font,1000,1000);const float profiles[][2]={{400,100},{900,100},{100,100},{400,200},{400,50},{650,150}};for(unsigned i=0;i<6;i++){hb_variation_t v[2]={{HB_TAG('w','g','h','t'),profiles[i][0]},{HB_TAG('w','d','t','h'),profiles[i][1]}};hb_font_set_variations(font,v,2);hb_buffer_t*buffer=hb_buffer_create();hb_buffer_add_utf8(buffer,"a",1,0,1);hb_buffer_set_direction(buffer,HB_DIRECTION_LTR);hb_buffer_set_script(buffer,HB_SCRIPT_LATIN);hb_buffer_set_language(buffer,hb_language_from_string("en",-1));hb_shape(font,buffer,NULL,0);unsigned n=0;const hb_glyph_info_t*info=hb_buffer_get_glyph_infos(buffer,&n);const hb_glyph_position_t*pos=hb_buffer_get_glyph_positions(buffer,NULL);if(n!=1)return 3;hb_glyph_extents_t extents;if(!hb_font_get_glyph_extents(font,info[0].codepoint,&extents))return 4;printf("%.0f %.0f %u %d %d %d %d %d\n",profiles[i][0],profiles[i][1],info[0].codepoint,pos[0].x_advance,extents.x_bearing,extents.y_bearing,extents.width,extents.height);hb_buffer_destroy(buffer);}hb_font_destroy(font);hb_face_destroy(face);hb_blob_destroy(blob);return 0;}
